import {
    Object3D,
    Mesh,
    PlaneGeometry,
    sRGBEncoding,
} from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{ imageUrl?: string, depthMapUrl?: string, meshUrl?: string }} assets
 * @property {string} textContent
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Array<{ name: string, params: any }>} cinematicPrimitives
 * @property {Record<string,string>} colors
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {Record<string,Function>} primitives
 */

/**
 * Create a hero‑subhead node: a textured plane with MSDF text overlay.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // --------------------------------------------------------------------
    // Root container
    // --------------------------------------------------------------------
    const root = new Object3D();
    if (config.position) root.position.fromArray(config.position);
    if (config.rotation) root.rotation.fromArray(config.rotation);
    if (config.scale) root.scale.fromArray(config.scale);

    // --------------------------------------------------------------------
    // Background textured plane
    // --------------------------------------------------------------------
    const planeGeo = new PlaneGeometry(1, 1, 1, 1);
    const imgUrl = config.assets && config.assets.imageUrl;
    const bgTexture = imgUrl ? ctx.textureLoader(imgUrl) : null;
    if (bgTexture) {
        bgTexture.encoding = sRGBEncoding;
        bgTexture.needsUpdate = true;
    }

    const bgMaterial = new MeshBasicNodeMaterial({
        map: bgTexture ? texture(bgTexture) : null,
        transparent: true,
    });

    const bgMesh = new Mesh(planeGeo, bgMaterial);
    // Preserve image aspect ratio – scale X accordingly.
    if (bgTexture && bgTexture.image && bgTexture.image.width && bgTexture.image.height) {
        const aspect = bgTexture.image.width / bgTexture.image.height;
        bgMesh.scale.set(aspect, 1, 1);
    }
    root.add(bgMesh);

    // --------------------------------------------------------------------
    // MSDF text overlay (headline)
    // --------------------------------------------------------------------
    const textMesh = createTextMesh({
        text: config.textContent,
        // Use the display typography token (Lora) – size relative to scene units.
        // Subhead scale is 0.2 scene‑units; we convert to a reasonable plane size.
        size: 0.2,
        // Color from design tokens – ink for high contrast.
        color: config.colors?.ink ?? '#16161d',
        // Align centre.
        anchorX: 'center',
        anchorY: 'middle',
        // Slight offset in front of the background plane.
        position: [0, 0, 0.01],
        // Font atlas region handling is internal to the helper.
        atlasRegion: { atlas: 0, rect: [0, 0, 512, 320] },
    });
    root.add(textMesh);

    // --------------------------------------------------------------------
    // Apply cinematic primitives (none in this spec, but keep loop for safety)
    // --------------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives[primitive.name];
            if (typeof fn === 'function') {
                fn(root, primitive.params);
            }
        }
    }

    // --------------------------------------------------------------------
    // Event handlers placeholder (no interactions defined)
    // --------------------------------------------------------------------
    root.userData.handlers = {};

    // --------------------------------------------------------------------
    // Cleanup routine
    // --------------------------------------------------------------------
    const timelines = [];
    root.userData.cleanup = () => {
        timelines.forEach(t => t.kill());

        planeGeo.dispose();
        bgMaterial.dispose();
        if (bgTexture) bgTexture.dispose();

        if (textMesh) {
            textMesh.traverse(child => {
                if (child.isMesh) {
                    child.geometry?.dispose();
                    child.material?.dispose?.();
                }
            });
        }
    };

    // --------------------------------------------------------------------
    // Return the assembled node
    // --------------------------------------------------------------------
    return root;
}
